import{_ as a,o as e,c as d,a4 as i}from"./chunks/framework.DAD9IEko.js";const m=JSON.parse('{"title":"示例 1：PI 参数调节基础","description":"","frontmatter":{"date":"2026-05-27T00:00:00.000Z","section":"电机控制","chapter":"simulation","chapterTitle":"仿真与调试","chapterOrder":10,"category":"仿真与调试","source":"motor","visibility":"public","title":"示例 1：PI 参数调节基础","tags":["motor-control"],"status":"learning","summary":"理解电流环带宽 `CLBW_HZ` 和速度环/电流环带宽比 `delta` 对系统响应的影响。","navGroup":"实践与验证","navGroupOrder":40},"headers":[],"relativePath":"content/motor/simulation/code-examples/01-pi-tuning-basic/README.md","filePath":"content/motor/simulation/code-examples/01-pi-tuning-basic/README.md","lastUpdated":1783096495000}'),o={name:"content/motor/simulation/code-examples/01-pi-tuning-basic/README.md"};function l(r,t,n,c,s,h){return e(),d("div",null,[...t[0]||(t[0]=[i('<h1 id="示例-1-pi-参数调节基础" tabindex="-1">示例 1：PI 参数调节基础 <a class="header-anchor" href="#示例-1-pi-参数调节基础" aria-label="Permalink to &quot;示例 1：PI 参数调节基础&quot;">​</a></h1><h2 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h2><p>理解电流环带宽 <code>CLBW_HZ</code> 和速度环/电流环带宽比 <code>delta</code> 对系统响应的影响。</p><h2 id="操作步骤" tabindex="-1">操作步骤 <a class="header-anchor" href="#操作步骤" aria-label="Permalink to &quot;操作步骤&quot;">​</a></h2><ol><li>启动仿真，选择任意电机和 MODE_SELECT_FOC (mode 3)</li><li>在 sidebar「可调参数」中修改 <code>FOC.CLBW_HZ</code> 和 <code>FOC.delta</code></li><li>点击「Save to C and compile」运行</li><li>对比不同参数下的电流阶跃响应</li></ol><h2 id="参数对照表" tabindex="-1">参数对照表 <a class="header-anchor" href="#参数对照表" aria-label="Permalink to &quot;参数对照表&quot;">​</a></h2><div class="kb-table-scroll"><table><thead><tr><th>组号</th><th>CLBW_HZ</th><th>delta</th><th>预期 iQ 响应</th><th>预期 Speed 响应</th></tr></thead><tbody><tr><td>A</td><td>50</td><td>20</td><td>慢速跟踪，无超调</td><td>很慢，但稳定</td></tr><tr><td>B</td><td>100</td><td>10</td><td>中等速度，轻微超调</td><td>中等速度</td></tr><tr><td>C</td><td>200</td><td>5</td><td>快速响应，可能有超调</td><td>快，可能振荡</td></tr><tr><td>D</td><td>500</td><td>5</td><td>非常快，可能振荡</td><td>快，可能不稳定</td></tr></tbody></table></div><h2 id="预期效果" tabindex="-1">预期效果 <a class="header-anchor" href="#预期效果" aria-label="Permalink to &quot;预期效果&quot;">​</a></h2><ul><li>CLBW_HZ 越大：iQ 阶跃响应越快，但噪声越大</li><li>delta 越小：速度环响应越快（速度环带宽 = 电流环带宽 / delta）</li><li>如果 iQ 振荡 → CLBW_HZ 设得太大，减小</li><li>如果 Speed 稳态有误差 → Ki_CODE 太小或为零</li></ul>',9)])])}const u=a(o,[["render",l]]);export{m as __pageData,u as default};
